import { useState, useEffect } from 'react';
import Login from './Login';
import DashboardCandidat from './components/DashboardCandidat';
import DashboardRecruteur from './components/DashboardRecruteur';
import Sauvegardees from './components/Sauvegardees';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import JobDetails from './components/JobDetails';
import EditJob from './components/EditJob';

function App() {
  const [user, setUser] = useState(() => {
    const savedUser = localStorage.getItem('user');
    return savedUser ? JSON.parse(savedUser) : null;
  });

  // États globaux
  const [jobs, setJobs] = useState([]);
  const [savedJobs, setSavedJobs] = useState(() => {
    const saved = localStorage.getItem('savedJobs');
    return saved ? JSON.parse(saved) : [];
  });

  // États de recherche et filtre globaux pour les dashboards
  const [search, setSearch] = useState('');
  const [activeTab, setActiveTab] = useState('all');

  useEffect(() => {
    if (user) {
      localStorage.setItem('user', JSON.stringify(user));
    } else {
      localStorage.removeItem('user');
    }
  }, [user]);

  useEffect(() => {
    localStorage.setItem('savedJobs', JSON.stringify(savedJobs));
  }, [savedJobs]);

  return (
    <Router>
      <div className="main-app">
        {user ? (
          <>
            <button onClick={() => setUser(null)}>Déconnexion</button>

            <Routes>
              <Route 
                path="/" 
                element={user.role === 'CANDIDAT' ? 
                  <DashboardCandidat 
                    jobs={jobs} 
                    setJobs={setJobs} 
                    savedJobs={savedJobs} 
                    setSavedJobs={setSavedJobs} 
                  /> : 
                  <DashboardRecruteur 
                    jobs={jobs} 
                    setJobs={setJobs} 
                    search={search} 
                    setSearch={setSearch} 
                    activeTab={activeTab} 
                    setActiveTab={setActiveTab} 
                  />
                } 
              />

              <Route 
                path="/candidat/sauvegardees" 
                element={<Sauvegardees jobs={jobs} savedJobs={savedJobs} />} 
              />

              <Route path="/job/:id" element={<JobDetails />} />
              <Route path="/edit-job/:id" element={<EditJob />} />

              <Route path="*" element={<Navigate to="/" />} />
            </Routes>
          </>
        ) : (
          <Login onLoginSuccess={setUser} />
        )}
      </div>
    </Router>
  );
}

export default App;
